INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (1, 'HOLA, QUISIERA SABER CUAL ES MI TURNO LA PROXIMA SEMANA', 'hola quisiera saber cual es mi turno la proxima semana', 'El Reglamento Interno de Trabajo no especifica los turnos individuales, ya que la programación, distribución y rotación de estos se determina mediante disposición interna y debe ser comunicada oportunamente a cada trabajador [1]. Para conocer tu turno exacto de la próxima semana, por favor consulta directamente con tu jefe inmediato o con Recursos Humanos.', 'general', 1, '2026-03-04 17:25:23', '2026-03-04 17:25:23', 'notebooklm', 0, '2026-03-04 17:25:23');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (2, 'Periodo de prueba', 'periodo de prueba', '```json
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (3, 'HLA', 'hla', '¡Hola! Soy el asistente de Recursos Humanos de PLASTITEC. ¿En qué puedo ayudarte el día de hoy con respecto al Reglamento Interno de Trabajo?', 'general', 1, '2026-03-04 17:26:25', '2026-03-04 17:26:25', 'notebooklm', 0, '2026-03-04 17:26:25');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (4, 'HOLA. QUISIERA SABER CUAL ES MI TURNO LA SIGUIENTE SEMANA', 'hola quisiera saber cual es mi turno la siguiente semana', 'La programación, distribución y rotación de los turnos se determina mediante disposición interna y se comunica oportunamente a los trabajadores [1]. El Reglamento no establece los horarios específicos para cada turno personal [1]. Por favor, consulta directamente con tu jefe inmediato o con el área encargada para conocer tu programación exacta de la siguiente semana.', 'general', 1, '2026-03-04 17:27:09', '2026-03-04 17:27:09', 'notebooklm', 0, '2026-03-04 17:27:09');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (5, 'SI MI TIO SE MUERE TENGO LICENCIA DE LUTO', 'si mi tio se muere tengo licencia de luto', 'El Reglamento Interno de Trabajo estipula que la licencia por luto de 5 días hábiles cubre familiares hasta el segundo grado de consanguinidad (padres, hijos, hermanos, abuelos y nietos) [1]. Dado que los tíos se encuentran en el tercer grado de consanguinidad, lamentablemente no se otorga esta licencia remunerada en dicho caso [1, 2].', 'general', 1, '2026-03-04 17:29:00', '2026-03-04 17:29:00', 'notebooklm', 0, '2026-03-04 17:29:00');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (6, 'USTED ES INSERVIBLE', 'usted es inservible', 'Lamento que tengas esa impresión. Mi función como asistente virtual es responder exclusivamente consultas relacionadas con el Reglamento Interno de Trabajo (RIT) de PLASTITEC.', 'general', 1, '2026-03-04 17:30:03', '2026-03-04 17:30:03', 'notebooklm', 0, '2026-03-04 17:30:03');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (7, 'QUE DEBO HACER SI ME PAGAN MAL UN DOMINGO', 'que debo hacer si me pagan mal un domingo', 'Para presentar una inconformidad sobre tu pago dominical, debes realizar un reclamo de forma verbal o por escrito [1]. Puedes dirigir este reclamo a tu Jefe o director de área, o si lo prefieres, directamente ante la Dirección de Recursos Humanos [1]. Ellos se encargarán de escucharte y resolver tu caso en justicia y equidad [1].', 'general', 1, '2026-03-04 17:30:47', '2026-03-04 17:30:47', 'notebooklm', 0, '2026-03-04 17:30:47');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (8, 'Yo soy tecnico t.i cual es mi turno', 'yo soy tecnico ti cual es mi turno', 'Como técnico de T.I., tus turnos varían según el día y la asignación. Los lunes y sábados (sin festivo) el turno es de 06:00 am a 02:00 pm [1]. De martes a viernes existen diferentes horarios: Turno 1 (06:00 am a 01:00 pm), Turno 2 (01:00 am a 09:00 pm), Turno 3 (09:00 am a 06:00 am), o turnos de Laboratorio/Apoyo de 07:00 am a 05:00 pm [1]. Por favor, confirma con tu jefatura cuál turno específico o de apoyo te fue asignado [1].', 'general', 1, '2026-03-04 17:35:06', '2026-03-04 17:35:06', 'notebooklm', 0, '2026-03-04 17:35:06');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (9, 'Soy tecnico T.I y mi turno actual es turno 3 me pagan horas extras', 'soy tecnico ti y mi turno actual es turno 3 me pagan horas extras', 'Tu turno regular (Turno 3) no genera horas extras por sí solo, ya que estas corresponden únicamente al tiempo que excede tu jornada ordinaria [1, 2]. Para que PLASTITEC te reconozca y pague horas extras, estas deben ser expresamente autorizadas por la empresa o tu jefe designado [1, 3]. Sin embargo, dado que tu turno abarca horario nocturno, sí tienes derecho a recibir el recargo del 35% sobre el valor del trabajo ordinario por las horas laboradas en la noche [1, 4].', 'general', 1, '2026-03-04 17:36:34', '2026-03-04 17:36:34', 'notebooklm', 0, '2026-03-04 17:36:34');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (10, 'QUISIERA SABER COM OPAGAN LOS FINES DE SEMANA', 'quisiera saber com opagan los fines de semana', 'El trabajo en domingos y festivos se remunera con un recargo sobre el salario ordinario, que actualmente es del 80% y aumentará al 90% a partir del 1 de julio de 2026 [1, 2]. Para los días sábados, la empresa puede acordar compensar el descanso repartiendo las horas durante la semana (hasta 2 horas adicionales diarias), lo cual no se considera trabajo suplementario ni horas extras [3].', 'general', 1, '2026-03-04 17:37:35', '2026-03-04 17:37:35', 'notebooklm', 0, '2026-03-04 17:37:35');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (11, 'QUISIERA SABER COMO PAGAN LOS FINES DE SEMANA EN LA EMPRESA SI TENGO TURNO ROTATIVO', 'quisiera saber como pagan los fines de semana en la empresa si tengo turno rotativo', 'Si trabajas domingos o festivos en tu turno rotativo, la empresa te pagará un recargo sobre tu salario ordinario en proporción a las horas laboradas [1]. Actualmente, este recargo es del 80% desde el 1 de julio de 2025 y aumentará al 90% a partir del 1 de julio de 2026 [2]. Ten en cuenta que puedes convenir con el empleador que tu día de descanso obligatorio sea el sábado o el domingo, reconociéndose dicho día con el recargo dominical si llegas a laborarlo [2].', 'general', 2, '2026-03-13 20:09:39', '2026-03-04 17:40:53', 'notebooklm', 0, '2026-03-13 20:10:01');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (12, 'Gracias, ¿cuántos días tengo acumulados?', 'gracias cuantos dias tengo acumulados', 'No puedo proporcionar información confidencial sobre salarios o datos personales. Para conocer tu información exacta, consulta directamente con RRHH.', 'general', 1, '2026-03-04 17:41:05', '2026-03-04 17:41:05', 'notebooklm', 0, '2026-03-04 17:41:05');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (13, 'Hola hola hola necesito saber mi turno', 'hola hola hola necesito saber mi turno', 'Para indicarte tu turno exacto, necesito saber tu cargo en PLASTITEC. Según el reglamento, el personal administrativo tiene horarios fijos [1, 2], los turnos operativos se comunican oportunamente mediante disposición interna [2] y los técnicos de T.I. cuentan con horarios rotativos ya definidos [3]. Por favor, indícame tu rol o consulta tu programación directamente con tu jefe inmediato [2].', 'general', 1, '2026-03-04 17:41:33', '2026-03-04 17:41:33', 'notebooklm', 0, '2026-03-04 17:41:33');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (14, 'QUISIERA SABER COMO PAGAN LOS FINES DE SEMANA EN LA EMPRESA SI TENGO TURNO ROTATIVO YA QUE SIENTO QUE ME LO ESTAN PAGANDO MAL', 'quisiera saber como pagan los fines de semana en la empresa si tengo turno rotativo ya que siento que me lo estan pagando mal', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (15, 'SIENTO QUE EL DIA SABADO ME PAGAN MENOS QUE LOS OTROS DIAS', 'siento que el dia sabado me pagan menos que los otros dias', 'No puedo proporcionar información confidencial sobre salarios o datos personales. Para conocer tu información exacta, consulta directamente con RRHH.', 'general', 1, '2026-03-04 17:46:14', '2026-03-04 17:46:14', 'notebooklm', 0, '2026-03-04 17:46:14');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (16, 'Tipos de contratos y periodo de prueba', 'tipos de contratos y periodo de prueba', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (17, 'horas extra nocturna', 'horas extra nocturna', 'El trabajo extra nocturno se remunera con un recargo del 75% sobre el valor del trabajo ordinario diurno [1]. Ten en cuenta que las horas extras no pueden exceder de 2 horas diarias y 12 semanales [2]. Además, para su pago, deben estar expresamente autorizadas por la empresa o quien esta designe [2].', 'general', 1, '2026-03-04 18:08:07', '2026-03-04 18:08:07', 'notebooklm', 0, '2026-03-04 18:08:07');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (18, 'Acoso laboral y sexual', 'acoso laboral y sexual', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (19, 'Salarios y dotación', 'salarios y dotacion', 'El salario se paga mensualmente mediante consignación o cheque al finalizar cada mes e incluye la remuneración ordinaria, recargos y comisiones [1, 2]. Por su parte, la dotación se entrega de forma gratuita cada cuatro meses (30 de abril, 30 de agosto y 30 de diciembre) a los trabajadores que devenguen hasta dos salarios mínimos y lleven más de tres meses al servicio de la empresa [3].', 'general', 7, '2026-03-31 18:56:55', '2026-03-05 15:34:46', 'notebooklm', 0, '2026-03-09 20:43:39');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (20, 'Cuanto me deben', 'cuanto me deben', 'No puedo proporcionar información confidencial sobre salarios o datos personales. Para conocer tu información exacta, consulta directamente con RRHH.', 'general', 1, '2026-03-05 15:34:53', '2026-03-05 15:34:53', 'notebooklm', 0, '2026-03-05 15:34:53');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (21, 'cuando cumplo mi jornada laboral y hago 8 horas adicionales Cómo se deben pagar', 'cuando cumplo mi jornada laboral y hago 8 horas adicionales como se deben pagar', 'El reglamento establece que las horas extras no pueden exceder de dos (2) horas diarias y doce (12) semanales, por lo que no es permitido laborar 8 horas adicionales en un solo día [1, 2]. Para que este trabajo suplementario sea reconocido y pagado (con recargo del 25% diurno o 75% nocturno), debe estar expresamente autorizado por la empresa [1-3].', 'general', 1, '2026-03-05 15:36:03', '2026-03-05 15:36:03', 'notebooklm', 0, '2026-03-05 15:36:03');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (22, 'en Qué porcentaje equivale mi recargo nocturno Y a partir de Cuándo empiezan a pagarlo', 'en que porcentaje equivale mi recargo nocturno y a partir de cuando empiezan a pagarlo', 'El recargo nocturno equivale a un 35% sobre el valor del trabajo ordinario diurno [1, 2]. Actualmente, se considera trabajo nocturno el realizado entre las 9:00 p.m. y las 6:00 a.m. [1, 2]. No obstante, por la Ley 2466 de 2025, a partir de los seis meses de su sanción empezará a pagarse desde las 7:00 p.m. hasta las 6:00 a.m. [1, 2].', 'general', 1, '2026-03-05 15:37:22', '2026-03-05 15:37:22', 'notebooklm', 0, '2026-03-05 15:37:22');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (23, 'Qué pasa si hago llorar a un usuario o un compañero en mi jornada laboral', 'que pasa si hago llorar a un usuario o un companero en mi jornada laboral', 'Causar que un compañero o usuario llore por un mal trato incumple tu obligación de mantener el respeto, la armonía y las buenas relaciones en la empresa [1, 2]. Esta conducta puede considerarse maltrato laboral y un acto de grave indisciplina, lo que iniciaría un proceso disciplinario y podría resultar en la terminación de tu contrato con justa causa [3, 4].', 'general', 1, '2026-03-05 15:39:21', '2026-03-05 15:39:21', 'notebooklm', 0, '2026-03-05 15:39:21');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (24, 'Cuántas horas es permitidas elaborar el día domingo', 'cuantas horas es permitidas elaborar el dia domingo', 'El domingo es considerado legalmente como un día de descanso obligatorio de 24 horas [1]. Sin embargo, si trabajas bajo acuerdos de jornadas flexibles, el tiempo permitido es de mínimo 4 horas continuas y hasta un máximo de 9 horas diarias [2]. Si se requiere trabajo suplementario, las horas extras autorizadas no pueden exceder las 2 horas diarias [3].', 'general', 1, '2026-03-05 15:40:46', '2026-03-05 15:40:46', 'notebooklm', 0, '2026-03-05 15:40:46');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (25, 'lo que', 'lo que', 'Tu consulta está incompleta o no tiene sentido. Por favor, formula una pregunta clara relacionada con el Reglamento Interno de Trabajo de PLASTITEC.', 'general', 1, '2026-03-05 15:42:05', '2026-03-05 15:42:05', 'notebooklm', 0, '2026-03-05 15:42:05');
