INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (27, 'Hola podría explicarme Qué es una hora extra dominical y un recargo dominical', 'hola podria explicarme que es una hora extra dominical y un recargo dominical', '```json
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (28, 'si yo cumplí mis horas extras semanales', 'si yo cumpli mis horas extras semanales', 'De acuerdo con el Reglamento Interno de Trabajo, las horas extras no pueden exceder el límite máximo de dos (2) horas diarias y doce (12) horas semanales [1, 2]. Si ya cumpliste tus 12 horas en la semana, no podrás realizar más trabajo suplementario durante ese periodo.', 'general', 1, '2026-03-05 15:54:10', '2026-03-05 15:54:10', 'notebooklm', 0, '2026-03-05 15:54:10');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (29, 'Sí yo trabajo mis horas extras semanales y trabajo el domingo 8 horas Esta sí cuentan como horas extras dominicales o recargos', 'si yo trabajo mis horas extras semanales y trabajo el domingo 8 horas esta si cuentan como horas extras dominicales o recargos', 'Si al trabajar el domingo excedes tu jornada ordinaria o la máxima legal semanal, esas 8 horas se consideran trabajo suplementario o horas extras [1]. Adicionalmente, por laborar en un día de descanso obligatorio (domingo), tienes derecho a recibir el recargo dominical correspondiente, el cual se aplica de manera progresiva [2, 3]. Por lo tanto, esas horas deben liquidarse como horas extras junto con su respectivo recargo dominical.', 'general', 1, '2026-03-05 15:54:37', '2026-03-05 15:54:37', 'notebooklm', 0, '2026-03-05 15:54:37');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (30, 'Que hago si no me pagan completo estos dias dominicales laborados', 'que hago si no me pagan completo estos dias dominicales laborados', 'Error: read ECONNRESET', 'general', 1, '2026-03-05 15:58:30', '2026-03-05 15:58:30', 'notebooklm', 0, '2026-03-05 15:58:30');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (31, 'Que hago si no me pagan mis horas extras dominicales completas', 'que hago si no me pagan mis horas extras dominicales completas', 'Si tienes inconformidades con el pago de tus horas extras dominicales, puedes solicitar a la empresa la relación detallada de tus horas laboradas junto con el soporte del pago [1]. Para solucionar el inconveniente, debes presentar un reclamo verbal o por escrito ante tu Jefe, Director de área, o directamente ante la Dirección de Recursos Humanos [2].', 'general', 1, '2026-03-05 15:59:27', '2026-03-05 15:59:27', 'notebooklm', 0, '2026-03-05 15:59:27');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (32, 'vinimos', 'vinimos', 'Hola. Te informo que mi función principal es resolver dudas y consultas exclusivamente sobre el Reglamento Interno de Trabajo (RIT) de PLASTITEC. ¿Tienes alguna duda puntual sobre el reglamento en la que te pueda ayudar?', 'general', 1, '2026-03-05 16:01:26', '2026-03-05 16:01:26', 'notebooklm', 0, '2026-03-05 16:01:26');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (33, 'Despues de 3 dias cuantos domingos son permitidos descontar', 'despues de 3 dias cuantos domingos son permitidos descontar', 'Cualquier ausencia o interrupción injustificada da lugar a la pérdida del día dominical de esa respectiva semana, por no haber laborado la semana completa [1]. El reglamento no establece un descuento de múltiples domingos por faltar 3 días; el descuento aplica por la semana de la inasistencia. Sin embargo, ten en cuenta que faltar totalmente a tus labores por tercera vez sin excusa suficiente constituye una falta grave [2].', 'general', 1, '2026-03-05 16:07:15', '2026-03-05 16:07:15', 'notebooklm', 0, '2026-03-05 16:07:15');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (34, 'Don Héctor yo solicité tres días de permisos no remunerados Cuántos domingos tendrían que descontarme', 'don hector yo solicite tres dias de permisos no remunerados cuantos domingos tendrian que descontarme', 'El Reglamento Interno establece que la pérdida del dominical ocurre por ausencias o interrupciones injustificadas [1]. Dado que tu ausencia fue por un permiso, tendrías derecho a la remuneración del descanso dominical en proporción al tiempo efectivamente laborado durante esa semana [2]. Te sugiero validar el cálculo exacto de tu nómina directamente con Recursos Humanos.', 'general', 1, '2026-03-05 16:09:45', '2026-03-05 16:09:45', 'notebooklm', 0, '2026-03-05 16:09:45');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (35, 'Yo tengo como básico 2,300 trabajo las horas semanales que son pero me hacen venir el domingo a trabajar 10 horas cuánto deben pagarme por ese domingo', 'yo tengo como basico 2300 trabajo las horas semanales que son pero me hacen venir el domingo a trabajar 10 horas cuanto deben pagarme por ese domingo', 'No puedo proporcionar información confidencial sobre salarios o datos personales. Para conocer tu información exacta, consulta directamente con RRHH.', 'general', 1, '2026-03-05 16:24:39', '2026-03-05 16:24:39', 'notebooklm', 0, '2026-03-05 16:24:39');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (36, 'inter yo solicité un permiso no remunerado para el día viernes sábado y lunes de la siguiente semana que la pregunta es', 'inter yo solicite un permiso no remunerado para el dia viernes sabado y lunes de la siguiente semana que la pregunta es', 'Error: read ECONNRESET', 'general', 1, '2026-03-05 16:25:55', '2026-03-05 16:25:55', 'notebooklm', 0, '2026-03-05 16:25:55');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (37, 'yo solicité tres días de permiso no remunerado el día viernes sábado y lunes de la siguiente semana Cómo hago para saber si tienen que descontarme uno o dos domingos', 'yo solicite tres dias de permiso no remunerado el dia viernes sabado y lunes de la siguiente semana como hago para saber si tienen que descontarme uno o dos domingos', 'Según el RIT, la pérdida del pago del descanso dominical ocurre cuando hay una ausencia injustificada que impide trabajar la semana completa [1]. Al tratarse de un permiso solicitado que abarca días de dos semanas distintas (viernes, sábado y lunes), te recomiendo confirmar directamente con Recursos Humanos cómo aplicarán la liquidación en tu caso particular.', 'general', 1, '2026-03-05 16:26:37', '2026-03-05 16:26:37', 'notebooklm', 0, '2026-03-05 16:26:37');
