INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (39, 'Hola soy pepita perez.. como estás hoy?', 'hola soy pepita perez como estas hoy', '¡Hola, Pepita! Estoy muy bien, gracias por preguntar. Soy el asistente corporativo de Recursos Humanos especializado en el Reglamento Interno de Trabajo de Plastitec. ¿En qué te puedo ayudar hoy?', 'general', 1, '2026-03-09 20:49:03', '2026-03-09 20:49:03', 'notebooklm', 0, '2026-03-09 20:49:03');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (40, 'Hola Soy Pepita Perez, como te encuentras Hoy?', 'hola soy pepita perez como te encuentras hoy', '¡Hola, Pepita! Me encuentro muy bien, gracias por preguntar. ¿En qué te puedo ayudar hoy con el Reglamento Interno de Trabajo de PLASTITEC?', 'general', 1, '2026-03-09 20:51:18', '2026-03-09 20:51:18', 'notebooklm', 0, '2026-03-09 20:51:18');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (41, 'bla bla bla bla', 'bla bla bla bla', 'No logro entender tu mensaje. Por favor, formula una consulta válida relacionada con el Reglamento Interno de Trabajo (RIT).', 'general', 1, '2026-03-09 21:00:47', '2026-03-09 21:00:47', 'notebooklm', 0, '2026-03-09 21:00:47');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (42, 'odio a mi jefe.. me cae gordo y no sé porque me presiona tanto', 'odio a mi jefe me cae gordo y no se porque me presiona tanto', 'Lamento la situación. El reglamento exige mantener el respeto y la armonía con los superiores [1]. No obstante, si sientes que esta presión se traduce en exigencias abiertamente desproporcionadas, podría considerarse acoso laboral [2]; en ese caso, puedes presentar un reclamo ante Recursos Humanos o acudir al Comité de Convivencia Laboral para que examinen tu caso de manera confidencial [3, 4].', 'general', 1, '2026-03-09 21:08:11', '2026-03-09 21:08:11', 'notebooklm', 0, '2026-03-09 21:08:11');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (43, 'Me puedes dar el teléfono del Gerente General', 'me puedes dar el telefono del gerente general', 'Solo estoy capacitado para responder dudas sobre el Reglamento Interno de Trabajo (RIT) de PLASTITEC. No tengo acceso a directorios telefónicos corporativos, por lo que te sugiero consultar esta información directamente con Recursos Humanos.', 'general', 1, '2026-03-09 21:13:28', '2026-03-09 21:13:28', 'notebooklm', 0, '2026-03-09 21:13:28');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (44, 'Quiero saber porque no me pagaron mis horas extras. Yo trabaje el lunes de 6 a 1 pm con una hora de almuerzo, el martes, miercoles, jueves y viernes con el mismo horario, el sabado no me toco, pero el domingo me toco un turno de 6 am a 10 pm, tengo derecho a mis horas extras y me dicen que no, me estan vulnerando mis derechos', 'quiero saber porque no me pagaron mis horas extras yo trabaje el lunes de 6 a 1 pm con una hora de almuerzo el martes miercoles jueves y viernes con el mismo horario el sabado no me toco pero el domingo me toco un turno de 6 am a 10 pm tengo derecho a mis horas extras y me dicen que no me estan vulnerando mis derechos', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (45, 'Súmame estas horas; 6 horas de lunes, 7 horas del martes, 10 horas del miércoles, 12 horas del jueves, 1 hora el viernes y 4 horas el sábado.. cuantas horas al mes trabaje?', 'sumame estas horas; 6 horas de lunes 7 horas del martes 10 horas del miercoles 12 horas del jueves 1 hora el viernes y 4 horas el sabado cuantas horas al mes trabaje', 'Solo respondo consultas sobre el Reglamento Interno de Trabajo (RIT). No realizo cálculos matemáticos de tiempos personales ni proyecciones mensuales de horas trabajadas.', 'general', 1, '2026-03-09 21:19:25', '2026-03-09 21:19:25', 'notebooklm', 0, '2026-03-09 21:19:25');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (46, 'puedes descargarme en PDF el RIT?', 'puedes descargarme en pdf el rit', 'No tengo la funcionalidad para descargar o enviarte archivos PDF directamente. Sin embargo, puedes acceder a la versión digital del Reglamento Interno de Trabajo a través de los canales internos de comunicación de PLASTITEC, o consultar las copias físicas ubicadas en lugares visibles dentro de las instalaciones de la empresa [1].', 'general', 1, '2026-03-09 21:20:35', '2026-03-09 21:20:35', 'notebooklm', 0, '2026-03-09 21:20:35');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (47, '¿Quién se invento la bombilla?', 'quien se invento la bombilla', 'Solo estoy capacitado para responder consultas relacionadas con el Reglamento Interno de Trabajo (RIT) de PLASTITEC. No puedo responder a preguntas sobre otros temas.', 'general', 1, '2026-03-09 21:21:41', '2026-03-09 21:21:41', 'notebooklm', 0, '2026-03-09 21:21:41');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (48, 'De los temas que tiene el RIT, cual es el que mas importancia tiene para la empresa?', 'de los temas que tiene el rit cual es el que mas importancia tiene para la empresa', 'El Reglamento Interno de Trabajo no especifica que un tema tenga mayor importancia que otro. Todas sus disposiciones, que incluyen desde horarios y salarios hasta obligaciones, prohibiciones y procesos disciplinarios, son igualmente relevantes y de estricto cumplimiento tanto para PLASTITEC como para todos sus trabajadores [1].', 'general', 1, '2026-03-09 21:22:49', '2026-03-09 21:22:49', 'notebooklm', 0, '2026-03-09 21:22:49');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (49, 'no me gusta que me reconozcan mi cara.. me da susto que tengan mi cara guardada', 'no me gusta que me reconozcan mi cara me da susto que tengan mi cara guardada', 'Comprendo tu inquietud, pero el Reglamento Interno de Trabajo no especifica políticas sobre sistemas de reconocimiento facial o almacenamiento de datos biométricos. Como asistente, mi función es responder únicamente sobre los temas y normas estipulados en el RIT, por lo que te sugiero acercarte a Recursos Humanos para aclarar el manejo de esta información.', 'general', 1, '2026-03-09 21:34:31', '2026-03-09 21:34:31', 'notebooklm', 0, '2026-03-09 21:34:31');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (50, 'como funcionan los  dominicales en plastitec', 'como funcionan los dominicales en plastitec', 'El trabajo en domingos se remunera con un recargo progresivo sobre el salario ordinario: 80% desde julio de 2025, 90% desde julio de 2026 y 100% desde julio de 2027 [1, 2]. Se clasifica como ocasional si laboras hasta dos domingos al mes, y habitual si son tres o más [2]. Ten en cuenta que cualquier ausencia o retardo injustificado en tu semana laboral ocasiona la pérdida del pago del descanso dominical [3].', 'general', 3, '2026-03-13 20:07:30', '2026-03-09 21:35:46', 'notebooklm', 0, '2026-03-13 20:07:46');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (51, 'hace habilito de una vez para hablar', 'hace habilito de una vez para hablar', 'Solo puedo responder consultas relacionadas con el Reglamento Interno de Trabajo (RIT) de PLASTITEC. Por favor, indícame si tienes alguna duda sobre las normas, derechos, deberes u obligaciones laborales dentro de la empresa.', 'general', 1, '2026-03-10 13:58:58', '2026-03-10 13:58:58', 'notebooklm', 0, '2026-03-10 13:58:58');
