INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (53, 'Que pasa si hago llorar a un compañero', 'que pasa si hago llorar a un companero', 'Hacer llorar a un compañero incumple tu deber de mantener el respeto y la armonía en el lugar de trabajo [1]. Dependiendo de la gravedad, podría considerarse maltrato o acoso laboral, lo cual constituye una falta grave [2, 3]. Estas conductas conllevan a un proceso disciplinario e incluso a la terminación del contrato con justa causa [3, 4].', 'general', 1, '2026-03-10 14:02:13', '2026-03-10 14:02:13', 'notebooklm', 0, '2026-03-10 14:02:13');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (54, 'Que pasa si llego tarde una vez', 'que pasa si llego tarde una vez', 'Si llegas tarde a la hora de entrada por primera vez (un retardo de hasta 5 minutos) sin una excusa suficiente, se considera una falta leve. La consecuencia será un llamado de atención verbal, el cual quedará registrado en tu hoja de vida [1].', 'general', 1, '2026-03-10 14:04:45', '2026-03-10 14:04:45', 'notebooklm', 0, '2026-03-10 14:04:45');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (55, 'Que es un descargo y en que me afecta', 'que es un descargo y en que me afecta', 'Un descargo es tu oportunidad formal, ya sea verbal o escrita, para defenderte y dar tu versión de los hechos ante una presunta falta disciplinaria [1, 2]. Te afecta directamente porque de esta diligencia dependerá si Recursos Humanos te absuelve o te impone una sanción disciplinaria [3]. Además, ten en cuenta que no asistir a la citación sin justificación constituye una falta grave y se tomará como un indicio en tu contra [4].', 'general', 1, '2026-03-10 14:05:38', '2026-03-10 14:05:38', 'notebooklm', 0, '2026-03-10 14:05:38');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (56, 'sí', 'si', '¿En qué te puedo asesorar hoy sobre el Reglamento Interno de Trabajo de PLASTITEC?', 'general', 1, '2026-03-10 14:07:45', '2026-03-10 14:07:45', 'notebooklm', 0, '2026-03-10 14:07:45');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (57, 'A qué número me puedo comunicar con recursos humanos', 'a que numero me puedo comunicar con recursos humanos', 'Puedes comunicarte con Recursos Humanos a través del correo electrónico d.rhumanos@plastitec-sa.com [1]. También puedes llamar a los números de contacto de la empresa: PBX (601) 261 47 06, (601) 260 47 54, 260 02 85 o 260 02 82 [1].', 'general', 1, '2026-03-10 14:09:17', '2026-03-10 14:09:17', 'notebooklm', 0, '2026-03-10 14:09:17');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (58, 'Que porcentaje valen los recargos', 'que porcentaje valen los recargos', 'Los recargos se liquidan sobre el valor del trabajo ordinario diurno así: 35% para el trabajo nocturno [1], 25% para el trabajo extra diurno y 75% para el trabajo extra nocturno [2]. Adicionalmente, el trabajo dominical y festivo tiene un recargo actual del 80%, el cual aumentará al 90% a partir del 1 de julio de 2026 [3, 4].', 'general', 1, '2026-03-10 14:18:17', '2026-03-10 14:18:17', 'notebooklm', 0, '2026-03-10 14:18:17');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (59, 'como', 'como', 'Tu mensaje parece estar incompleto. Por favor, formula una pregunta específica sobre el Reglamento Interno de Trabajo de PLASTITEC para poder ayudarte.', 'general', 1, '2026-03-10 14:40:27', '2026-03-10 14:40:27', 'notebooklm', 0, '2026-03-10 14:40:27');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (60, 'Que debo hacer para denunciar acoso laboral?', 'que debo hacer para denunciar acoso laboral', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (61, 'que dice la pagina web de plastitec sobre el reglamento interno del trabajo', 'que dice la pagina web de plastitec sobre el reglamento interno del trabajo', 'Los documentos no detallan información específica sobre una página web. Sin embargo, el reglamento establece que este debe publicarse físicamente en la cartelera principal y en lugares visibles, así como en formato digital a través de los canales internos de comunicación de la empresa [1, 2].', 'general', 1, '2026-03-13 16:40:04', '2026-03-13 16:40:04', 'notebooklm', 0, '2026-03-13 16:40:04');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (62, 'Me estas respondiendo muy agresivo, me puedes hablar mas bonito?', 'me estas respondiendo muy agresivo me puedes hablar mas bonito', 'Lamento si te he dado esa impresión, mi intención es ser claro y directo. Recuerda que estoy aquí para responder exclusivamente consultas sobre el Reglamento Interno de Trabajo (RIT) de PLASTITEC. ¿Tienes alguna duda laboral en la que pueda ayudarte?', 'general', 1, '2026-03-13 16:41:30', '2026-03-13 16:41:30', 'notebooklm', 0, '2026-03-13 16:41:30');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (63, 'si , tengo una duda, pero tengo miedo que te digo me regañe mi jefe.. que puedo hacer?', 'si tengo una duda pero tengo miedo que te digo me regane mi jefe que puedo hacer', 'Puedes presentar tu duda o reclamo directamente a la Dirección de Recursos Humanos, quienes te escucharán y resolverán la situación con justicia y equidad [1]. Si tu temor se debe a posibles represalias o maltratos, ten en cuenta que el Comité de Convivencia Laboral tramita todas las quejas garantizando el principio de estricta confidencialidad [2]. Tus derechos están protegidos por el reglamento, ¿en qué te puedo ayudar?', 'general', 1, '2026-03-13 16:42:44', '2026-03-13 16:42:44', 'notebooklm', 0, '2026-03-13 16:42:44');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (64, '“ARTICULO 107. EFECTO JURIDICO. El reglamento hace parte del contrato individual de trabajo de cada uno de los trabajadores del respectivo establecimiento, salvo estipulación en contrario, que, sin embargo, sólo puede ser favorable al trabajador.”', '“articulo 107 efecto juridico el reglamento hace parte del contrato individual de trabajo de cada uno de los trabajadores del respectivo establecimiento salvo estipulacion en contrario que sin embargo solo puede ser favorable al trabajador”', 'Efectivamente, el Reglamento Interno de Trabajo de PLASTITEC hace parte integral de los contratos individuales de todos los trabajadores, y cualquier estipulación en contrario solo será válida si resulta más favorable para el empleado [1]. Cabe aclarar que en nuestro reglamento, este principio jurídico general se encuentra establecido desde el Artículo 1 [1].', 'general', 1, '2026-03-13 17:06:17', '2026-03-13 17:06:17', 'notebooklm', 0, '2026-03-13 17:06:17');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (65, 'Asuntos sindicales y fueros', 'asuntos sindicales y fueros', 'Un sindicato es una asociación de trabajadores agrupados para la defensa y promoción de sus intereses sociales, económicos y profesionales [1]. La estabilidad laboral reforzada o fuero protege a ciertos trabajadores contra despidos discriminatorios [2]. Entre los fueros reconocidos están el de maternidad, paternidad, salud, sindical, acoso laboral y pre pensionado, brindando garantías especiales según cada caso [3-5].', 'general', 1, '2026-03-13 17:13:56', '2026-03-13 17:13:56', 'notebooklm', 0, '2026-03-13 17:13:56');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (66, 'Descansos, vacaciones y permisos', 'descansos vacaciones y permisos', 'Tienes derecho a descansos remunerados los domingos y festivos de ley [1]. Al cumplir un año de labores, te corresponden 15 días hábiles consecutivos de vacaciones remuneradas [2]. También puedes solicitar permisos para calamidad doméstica, citas médicas, sufragio, luto y otras licencias legales, siempre que avises oportunamente y presentes los soportes requeridos [3-5].', 'general', 1, '2026-03-13 17:19:46', '2026-03-13 17:19:46', 'notebooklm', 0, '2026-03-13 17:19:46');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (67, 'Horas extras y recargos', 'horas extras y recargos', 'Las horas extras deben ser expresamente autorizadas por la empresa y no pueden exceder 2 horas diarias ni 12 semanales [1, 2]. Los recargos aplicables sobre el valor ordinario son: 35% para el trabajo nocturno [3], 25% para el trabajo extra diurno y 75% para el trabajo extra nocturno [2]. Además, el trabajo dominical y festivo tiene un recargo progresivo que inicia en 80% a partir del 1 de julio de 2025 [4, 5].', 'general', 1, '2026-03-13 17:25:26', '2026-03-13 17:25:26', 'notebooklm', 0, '2026-03-13 17:25:26');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (68, 'Licencias legales', 'licencias legales', 'El RIT contempla licencias remuneradas por maternidad, paternidad, parentales compartidas y por luto [1-5]. Además, se otorgan licencias para asistir a citas médicas de urgencias o especialistas [6], acompañamiento escolar obligatorio de los hijos [7] y para atender citaciones judiciales o legales [8]. Para disfrutar de estas licencias, debes solicitar la autorización correspondiente y presentar los debidos soportes a Recursos Humanos en los tiempos estipulados [1, 6, 9].', 'general', 1, '2026-03-13 17:26:30', '2026-03-13 17:26:30', 'notebooklm', 0, '2026-03-13 17:26:30');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (69, 'Obligaciones y régimen disciplinario', 'obligaciones y regimen disciplinario', 'Tus obligaciones principales incluyen realizar tu labor personalmente, cumplir las instrucciones de tus superiores, guardar confidencialidad sobre la información de la empresa y acatar las normas de seguridad en el trabajo [1-3]. Ante un posible incumplimiento, el régimen disciplinario garantiza el debido proceso mediante una etapa de citación a descargos, práctica de pruebas y la posibilidad de presentar recursos de reposición y apelación frente a las decisiones tomadas [4-7].', 'general', 1, '2026-03-13 17:27:46', '2026-03-13 17:27:46', 'notebooklm', 0, '2026-03-13 17:27:46');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (70, 'entiendo que no puedas dar información pero con cuantas hora de trabajo tengo derecho a pago de horas extras', 'entiendo que no puedas dar informacion pero con cuantas hora de trabajo tengo derecho a pago de horas extras', 'Error: Authentication expired. Run notebooklm-mcp-server auth to re-authenticate.', 'general', 2, '2026-04-14 21:16:21', '2026-03-13 18:10:38', 'notebooklm', 0, '2026-04-14 21:16:21');
