INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (72, 'me puedes descargar el RIT por favor', 'me puedes descargar el rit por favor', 'Como asistente virtual no puedo descargar ni enviar archivos. Sin embargo, te informo que el Reglamento Interno de Trabajo está publicado en dos copias físicas en lugares visibles de la empresa, y también se encuentra disponible en formato digital a través de los canales internos de comunicación [1].', 'general', 1, '2026-03-13 18:14:24', '2026-03-13 18:14:24', 'notebooklm', 0, '2026-03-13 18:14:24');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (73, 'ehhh parce.. no se que hacer.. esta nomina no me cuadra.. me pagaron menos', 'ehhh parce no se que hacer esta nomina no me cuadra me pagaron menos', 'Error: Authentication expired. Run notebooklm-mcp-server auth to re-authenticate.', 'general', 2, '2026-04-14 21:09:18', '2026-03-13 18:16:44', 'notebooklm', 0, '2026-04-14 21:09:18');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (74, 'Me puedes dar los lin donde puede ver mi plata pagada', 'me puedes dar los lin donde puede ver mi plata pagada', 'No puedo proporcionar información confidencial sobre salarios o datos personales. Para conocer tu información exacta, consulta directamente con RRHH.', 'general', 1, '2026-03-13 18:17:57', '2026-03-13 18:17:57', 'notebooklm', 0, '2026-03-13 18:17:57');
