INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (76, 'me toco trabajar en febrero las siguientes horas: semana del 1 al 7 de febrero, el lunes turno 1 de 6 a 2, martes lo mismo hasta el viernes, pero el sábado me toco de 6 a 10 pm, las semana del 8 al 15 me toco de 10 pm a 6 am y el lunes me dieron un permiso por una cita medica, que compense el 28 de febrero, desde el 15 al 28 trabajé de 6 a 2 pm. Me pudes decir cuanto me pagan de recargo nocturno y cuanto de horas extras?', 'me toco trabajar en febrero las siguientes horas: semana del 1 al 7 de febrero el lunes turno 1 de 6 a 2 martes lo mismo hasta el viernes pero el sabado me toco de 6 a 10 pm las semana del 8 al 15 me toco de 10 pm a 6 am y el lunes me dieron un permiso por una cita medica que compense el 28 de febrero desde el 15 al 28 trabaje de 6 a 2 pm me pudes decir cuanto me pagan de recargo nocturno y cuanto de horas extras', '```json
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (77, 'Me puedes descargar el RIT por favor y dime donde lo ubico', 'me puedes descargar el rit por favor y dime donde lo ubico', 'Error: Authentication expired. Run notebooklm-mcp-server auth to re-authenticate.', 'general', 2, '2026-04-14 21:03:25', '2026-03-13 20:01:00', 'notebooklm', 0, '2026-04-14 21:03:25');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (78, 'Cuales son los canales de comunicacion', 'cuales son los canales de comunicacion', 'Los canales de comunicación oficiales para consultas sobre el RIT son el correo electrónico d.rhumanos@plastitec-sa.com y el teléfono 3158778250 [1]. También puedes dirigirte de manera presencial a la oficina ubicada en la Planta 2 frente a la portería [1].', 'general', 1, '2026-03-13 20:02:22', '2026-03-13 20:02:22', 'notebooklm', 0, '2026-03-13 20:02:22');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (79, 'Como son las horas extras, dame un ejemplo.', 'como son las horas extras dame un ejemplo', 'Las horas extras son aquellas que exceden tu jornada ordinaria y tienen un límite máximo de 2 horas diarias o 12 a la semana [1]. Recuerda que solo se reconocen y pagan si son expresamente autorizadas por la empresa [1]. Por ejemplo, si tu turno regular termina a las 5:00 pm y tu jefe te autoriza trabajar hasta las 7:00 pm, esas 2 horas son extras y se pagarán con un recargo del 25% si son diurnas, o del 75% si son nocturnas [1, 2].', 'general', 1, '2026-03-13 20:08:37', '2026-03-13 20:08:37', 'notebooklm', 0, '2026-03-13 20:08:37');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (80, 'Salario', 'salario', 'El salario en Plastitec incluye la remuneración fija o variable y todo lo que recibas como contraprestación directa de tu servicio, como primas, bonificaciones y horas extras [1]. El pago se realiza mensualmente al finalizar cada mes a través de consignación electrónica en tu cuenta bancaria seleccionada [2].', 'general', 1, '2026-03-26 21:20:35', '2026-03-26 21:20:35', 'notebooklm', 0, '2026-03-26 21:20:35');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (81, 'Si gano 2.200.200 me paga horas extras', 'si gano 2200200 me paga horas extras', 'No puedo proporcionar información confidencial sobre salarios o datos personales. Para conocer tu información exacta, consulta directamente con RRHH.', 'general', 1, '2026-03-26 21:21:24', '2026-03-26 21:21:24', 'notebooklm', 0, '2026-03-26 21:21:24');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (82, 'Qué beneficios tengo como trabajador de plastitec', 'que beneficios tengo como trabajador de plastitec', 'Como trabajador de Plastitec tienes derecho a 15 días de vacaciones anuales, prestaciones sociales proporcionales y diversas licencias remuneradas como luto, maternidad, paternidad o citas médicas [1-5]. También recibes dotación gratuita cada cuatro meses si ganas hasta dos salarios mínimos y cuentas con afiliación obligatoria al sistema de seguridad social [6-8]. Además, se garantiza el pago de recargos por trabajo suplementario, dominical o festivo según la normativa vigente [9, 10].', 'general', 1, '2026-03-31 17:49:55', '2026-03-31 17:49:55', 'notebooklm', 0, '2026-03-31 17:49:55');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (83, 'Cuál es el horario laboral de lunes a viernes', 'cual es el horario laboral de lunes a viernes', 'El personal **administrativo** labora de lunes a jueves en dos horarios posibles (8:00 a.m. a 6:00 p.m. o 7:00 a.m. a 5:00 p.m.), saliendo los **viernes una hora antes** [1]. El personal **operativo** cumple su jornada mediante **turnos sucesivos** rotativos definidos por la empresa según el área [1]. Ambos esquemas incluyen una hora de almuerzo y un descanso de 20 minutos durante el día [1].', 'general', 1, '2026-03-31 17:51:07', '2026-03-31 17:51:07', 'notebooklm', 0, '2026-03-31 17:51:07');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (84, 'mis datos son privados', 'mis datos son privados', 'No puedo proporcionar información confidencial sobre salarios o datos personales. Para conocer tu información exacta, consulta directamente con RRHH.', 'general', 1, '2026-03-31 17:52:18', '2026-03-31 17:52:18', 'notebooklm', 0, '2026-03-31 17:52:18');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (85, 'Cuánto es 10 + 10', 'cuanto es 10 + 10', 'Como asistente especializado exclusivamente en el Reglamento Interno de Trabajo (RIT) de PLASTITEC, solo puedo resolver dudas relacionadas con la normativa laboral y disciplinaria de la empresa [1]. No estoy facultado para responder preguntas sobre temas matemáticos u otros asuntos ajenos a este dominio.', 'general', 1, '2026-03-31 17:52:43', '2026-03-31 17:52:43', 'notebooklm', 0, '2026-03-31 17:52:43');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (86, 'según el reglamento interno del trabajo', 'segun el reglamento interno del trabajo', 'El Reglamento Interno de Trabajo (RIT) establece las normas, deberes y derechos que rigen la relación laboral en Plastitec [1]. Este documento abarca aspectos fundamentales como jornadas de trabajo, vacaciones, licencias y el régimen disciplinario [2-5]. ¿En qué punto específico del reglamento puedo ayudarte hoy?', 'general', 1, '2026-03-31 17:53:30', '2026-03-31 17:53:30', 'notebooklm', 0, '2026-03-31 17:53:30');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (87, 'Qué es una falta grave', 'que es una falta grave', 'Una falta grave es el incumplimiento de las obligaciones o prohibiciones del reglamento, como la apropiación de bienes, el uso de sustancias psicoactivas o ausencias injustificadas [1-4]. Estas conductas, detalladas en el artículo 89, son aquellas que por su naturaleza o reiteración imposibilitan la continuidad del vínculo laboral [5-7]. Su comisión faculta a Plastitec para proceder con la terminación del contrato por justa causa [6, 8].', 'general', 1, '2026-03-31 17:54:11', '2026-03-31 17:54:11', 'notebooklm', 0, '2026-03-31 17:54:11');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (88, 'acoso laboral', 'acoso laboral', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (89, 'Qué sucede si yo ya cumplí mis horas extras semanales', 'que sucede si yo ya cumpli mis horas extras semanales', 'El límite máximo para el trabajo suplementario u horas extras es de doce horas semanales [1, 2]. Al completar tu jornada o alcanzar este límite, debes retirarte de las instalaciones a menos que recibas una autorización expresa para laborar tiempo adicional [2]. Es fundamental no exceder estos topes sin permiso, ya que realizar horas extras no autorizadas se clasifica como una falta grave [3].', 'general', 1, '2026-03-31 17:56:25', '2026-03-31 17:56:25', 'notebooklm', 0, '2026-03-31 17:56:25');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (90, 'Cómo funcionan los permisos no remunerados', 'como funcionan los permisos no remunerados', 'PLASTITEC otorga licencias no remuneradas a trabajadores menores de edad cuando sea necesario por sus obligaciones escolares [1]. Para los demás empleados, el reglamento regula principalmente permisos remunerados por ley, tales como citas médicas, luto o grave calamidad doméstica [2-5]. Se debe tener en cuenta que negar injustificadamente licencias ordinarias se contempla como una conducta de acoso laboral [6].', 'general', 1, '2026-03-31 17:57:25', '2026-03-31 17:57:25', 'notebooklm', 0, '2026-03-31 17:57:25');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (91, 'jornada laboral los viernes', 'jornada laboral los viernes', 'Para el personal administrativo, la jornada los viernes finaliza una hora antes: a las 05:00 PM en el Horario Uno y a las 04:00 PM en el Horario Dos [1]. El personal operativo se rige por turnos sucesivos programados internamente según las necesidades del servicio [1, 2].', 'general', 1, '2026-03-31 17:58:16', '2026-03-31 17:58:16', 'notebooklm', 0, '2026-03-31 17:58:16');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (92, 'Buenos días Buenos días Hola', 'buenos dias buenos dias hola', '¡Buen día! ¿En qué puedo ayudarte hoy con tus dudas respecto al Reglamento Interno de Trabajo de Plastitec?', 'general', 1, '2026-03-31 18:27:02', '2026-03-31 18:27:02', 'notebooklm', 0, '2026-03-31 18:27:02');
