INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (94, 'cuantas horas trabaje ayer', 'cuantas horas trabaje ayer', 'No puedo proporcionar información confidencial sobre salarios o datos personales. Para conocer tu información exacta, consulta directamente con RRHH.', 'general', 1, '2026-03-31 18:28:37', '2026-03-31 18:28:37', 'notebooklm', 0, '2026-03-31 18:28:37');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (95, 'cuantas horas de trabajo segun el reglamento debo trabajar', 'cuantas horas de trabajo segun el reglamento debo trabajar', 'Para el año 2026, la jornada laboral máxima en PLASTITEC es de 42 horas semanales [1]. Estas horas pueden distribuirse en 5 o 6 días a la semana mediante acuerdo, garantizando siempre tu día de descanso obligatorio [1, 2]. El horario exacto y la distribución de turnos dependerán de si realizas labores administrativas u operativas [3, 4].', 'general', 1, '2026-03-31 18:29:22', '2026-03-31 18:29:22', 'notebooklm', 0, '2026-03-31 18:29:22');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (96, 'Cuántas horas puedo trabajar en el día o por turno', 'cuantas horas puedo trabajar en el dia o por turno', 'Puedes laborar en jornadas diarias flexibles de entre cuatro y nueve horas, siempre que no excedas el promedio semanal de 42 horas [1]. Para turnos sucesivos de operación continua, el límite es de seis horas al día [1]. Recuerda que las horas extras están limitadas a un máximo de dos horas diarias [2, 3].', 'general', 1, '2026-03-31 18:37:45', '2026-03-31 18:37:45', 'notebooklm', 0, '2026-03-31 18:37:45');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (97, 'q hubo chino ,. e cuenta que puedo acer si no voy a travajar hoy', 'q hubo chino e cuenta que puedo acer si no voy a travajar hoy', 'Debes avisar inmediatamente a tu jefe o a Recursos Humanos sobre tu inasistencia [1, 2]. Ten en cuenta que faltar al trabajo sin una excusa justificada conlleva la pérdida del pago dominical [3]. Esta conducta también puede generar una sanción de suspensión de hasta ocho días por primera vez [4].', 'general', 1, '2026-03-31 18:37:59', '2026-03-31 18:37:59', 'notebooklm', 0, '2026-03-31 18:37:59');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (98, 'música conversación', 'musica conversacion', '{
