INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (100, 'Cómo denuncio una cosa laboral', 'como denuncio una cosa laboral', 'Puedes presentar tus reclamos por escrito de forma respetuosa ante tu jefe inmediato o directamente en la Dirección de Recursos Humanos [1, 2]. Para situaciones de acoso laboral o sexual, debes acudir al Comité de Convivencia Laboral para iniciar el proceso confidencial correspondiente [3-5]. Tienes derecho a contar con la asesoría de tu sindicato para tramitar cualquier queja relacionada con tu trabajo [2].', 'general', 1, '2026-03-31 18:39:57', '2026-03-31 18:39:57', 'notebooklm', 0, '2026-03-31 18:39:57');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (101, 'Cuánto es el salario mínimo', 'cuanto es el salario minimo', 'El Reglamento Interno de Trabajo de Plastitec establece que todo salario debe respetar siempre el salario mínimo legal mensual vigente (SMLMV) [1, 2]. Ten en cuenta que el valor numérico exacto no se detalla en el reglamento, pues este es fijado anualmente por el Gobierno Nacional y las leyes externas aplicables [1].', 'general', 1, '2026-03-31 18:41:25', '2026-03-31 18:41:25', 'notebooklm', 0, '2026-03-31 18:41:25');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (102, 'si trabajo hoy 5 horas y y mañana 10 y el lunes 4 cuantas horas me faltan para completar las semanas permitidas', 'si trabajo hoy 5 horas y y manana 10 y el lunes 4 cuantas horas me faltan para completar las semanas permitidas', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (103, 'como me puedo unir al sindicato', 'como me puedo unir al sindicato', 'Tienes el derecho fundamental a la libre asociación y la empresa tiene prohibido limitar o presionar este ejercicio [1]. Para unirte, debes contactar directamente a la organización sindical de tu interés [2]. El reglamento garantiza que no serás coartado para afiliarte, permanecer o retirarte de un sindicato [3].', 'general', 1, '2026-03-31 18:45:55', '2026-03-31 18:45:55', 'notebooklm', 0, '2026-03-31 18:45:55');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (104, '#porquetrabajo', '#porquetrabajo', 'Solo puedo responder consultas relacionadas con el Reglamento Interno de Trabajo (RIT) de Plastitec. Si tienes dudas sobre temas como permisos, horarios, vacaciones o normas de conducta, con gusto te ayudaré.', 'general', 1, '2026-03-31 18:51:12', '2026-03-31 18:51:12', 'notebooklm', 0, '2026-03-31 18:51:12');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (105, 'fui jurado que hago para mi dia de permiso', 'fui jurado que hago para mi dia de permiso', 'Para tramitar tu permiso por ser jurado, debes presentar la citación oficial a tu jefe inmediato y a Recursos Humanos con la mayor anticipación posible [1, 2]. Una vez cumplida la labor, es obligatorio entregar el certificado de asistencia ese mismo día o a más tardar el siguiente para legalizar tu licencia remunerada [2, 3]. Este permiso cubre el tiempo estrictamente necesario para la diligencia y retorno al trabajo [4].', 'general', 2, '2026-04-14 15:00:29', '2026-03-31 18:51:58', 'notebooklm', 0, '2026-04-14 15:00:49');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (106, 'hasta cuando puedo pedir el permiso .. cuantos días', 'hasta cuando puedo pedir el permiso cuantos dias', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (107, 'Cómo funcionan los recargos', 'como funcionan los recargos', 'El recargo nocturno es del 35%, las horas extras diurnas del 25% y las nocturnas del 75% [1, 2]. En cuanto a dominicales y festivos, el recargo actual es del 80% y aumentará gradualmente al 90% en julio de 2026 y al 100% en julio de 2027 [3-5].', 'general', 1, '2026-03-31 18:56:18', '2026-03-31 18:56:18', 'notebooklm', 0, '2026-03-31 18:56:18');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (108, 'Cuáles son los horarios que maneja plastitech', 'cuales son los horarios que maneja plastitech', 'El personal administrativo cuenta con dos horarios de lunes a jueves (8:00 a.m. a 6:00 p.m. o 7:00 a.m. a 5:00 p.m.), ambos con finalización anticipada los viernes [1]. Para el personal operativo, se establecen turnos sucesivos rotativos que son comunicados oportunamente según las necesidades operativas de la empresa [1].', 'general', 1, '2026-03-31 19:11:53', '2026-03-31 19:11:53', 'notebooklm', 0, '2026-03-31 19:11:53');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (109, 'cuántos días de vacaciones tengo', 'cuantos dias de vacaciones tengo', 'Según el reglamento, tienes derecho a quince (15) días hábiles de vacaciones remuneradas por cada año de servicios prestados [1]. En contratos por obra o a término fijo, se te reconocerán de forma proporcional al tiempo que hayas laborado [2], [3], [4]. Para conocer tu saldo de días acumulado a la fecha, te sugiero consultar directamente con RRHH, ya que ellos llevan el registro oficial [4].', 'general', 1, '2026-03-31 19:13:54', '2026-03-31 19:13:54', 'notebooklm', 0, '2026-03-31 19:13:54');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (110, 'que es rit?', 'que es rit', 'El **RIT** es el Reglamento Interno de Trabajo prescrito por **PLASTITEC S.A.S.**, cuyas disposiciones son de obligatorio cumplimiento tanto para la empresa como para todos sus colaboradores [1]. Este documento se integra a los **contratos individuales de trabajo** y establece las normas, deberes y derechos que rigen nuestra relación laboral [1, 2].', 'general', 1, '2026-03-31 19:26:28', '2026-03-31 19:26:28', 'notebooklm', 0, '2026-03-31 19:26:28');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (111, 'QUE DIA ES HOY?', 'que dia es hoy', 'Como asistente especializado de PLASTITEC, mi función se limita exclusivamente a resolver dudas relacionadas con el Reglamento Interno de Trabajo (RIT). Por lo tanto, no puedo responder a consultas sobre temas ajenos a este documento.', 'general', 1, '2026-03-31 19:41:23', '2026-03-31 19:41:23', 'notebooklm', 0, '2026-03-31 19:41:23');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (112, 'Cuál es la política de calidad', 'cual es la politica de calidad', 'Plastitec mantiene un compromiso constante con sus clientes, documentando y manteniendo todos sus procesos para entregar productos que cumplan con sus expectativas [1, 2]. Además, el área de Gestión de Calidad vigila el cumplimiento de las Buenas Prácticas de Manufactura (BPM) y la norma ISO 13485 [3].', 'general', 1, '2026-04-08 20:20:45', '2026-04-08 20:20:45', 'notebooklm', 0, '2026-04-08 20:20:45');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (113, 'Cómo debemos aplicar las bpm', 'como debemos aplicar las bpm', 'Para aplicar las BPM, debes seguir los instructivos de ingreso usando la dotación completa (cofia, protección auditiva y uniforme limpio) sin maquillaje ni joyas [1-3]. Es vital cumplir con el lavado de manos, no ingresar alimentos ni celulares a producción y evitar que cualquier producto o caja toque el piso [4-6]. Recuerda que cumplir estas normas de higiene es una obligación esencial para garantizar la calidad en todos nuestros procesos [7].', 'general', 1, '2026-04-08 20:23:56', '2026-04-08 20:23:56', 'notebooklm', 0, '2026-04-08 20:23:56');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (114, 'Cuáles son las normas de ingreso al vestidor', 'cuales son las normas de ingreso al vestidor', 'Antes de ingresar al vestidor, es obligatorio colocarse la **cofia** y la **protección auditiva**, asegurándose de no llevar ningún tipo de **maquillaje** [1-3]. Debe retirarse la ropa de calle y joyas para guardarlas en el **locker asignado**, dejando los zapatos de calle dentro de una bolsa plástica [1, 3]. Finalmente, póngase la **blusa blanca** y proceda a **lavar y desinfectar sus manos** siguiendo el instructivo correspondiente [1, 3].', 'general', 1, '2026-04-08 20:24:49', '2026-04-08 20:24:49', 'notebooklm', 0, '2026-04-08 20:24:49');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (115, 'como funcionan los recargos en plastitec', 'como funcionan los recargos en plastitec', 'El trabajo nocturno tiene un recargo del 35%, mientras que las horas extras diurnas y nocturnas se pagan con un 25% y 75% adicional respectivamente [1, 2]. Para domingos y festivos, el recargo es del 80% desde julio de 2025, aumentando gradualmente hasta el 100% en 2027 [3, 4]. Estos valores se calculan sobre el salario ordinario y no son acumulables entre sí [2, 4].', 'general', 1, '2026-04-08 20:26:10', '2026-04-08 20:26:10', 'notebooklm', 0, '2026-04-08 20:26:10');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (116, 'ejemplo de instructivos clave Cómo realizar las preguntas y unos ejemplos', 'ejemplo de instructivos clave como realizar las preguntas y unos ejemplos', '```json
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (117, 'Cual es paso a paso para ingresar a las áreas grises.', 'cual es paso a paso para ingresar a las areas grises', 'Antes de ingresar al vestier, debes colocarte la cofia y protección auditiva sin usar maquillaje [1]. Posteriormente, guarda tu ropa de calle y joyas en el locker para ponerte la blusa blanca y lavarte las manos según el instructivo [1]. Por último, ponte el uniforme, usa la cinta para quitar partículas y colócate guantes desinfectados sobre la dotación [1].', 'general', 1, '2026-04-14 14:41:41', '2026-04-14 14:41:41', 'notebooklm', 0, '2026-04-14 14:41:41');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (118, '¿Cómo se realiza el lavado de manos según el instructivo?', 'como se realiza el lavado de manos segun el instructivo', 'Para realizar el lavado correcto, debes humedecer manos y brazos hasta el codo, aplicar jabón antibacterial y frotar palmas, dorsos y dedos entrelazados durante al menos 30 segundos [1]. Luego, enjuaga con abundante agua hasta remover todo el jabón y seca completamente con una toalla de papel de un solo uso [1].', 'general', 1, '2026-04-14 21:19:10', '2026-04-14 21:19:10', 'notebooklm', 0, '2026-04-14 21:19:10');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (119, '¿Cuáles son las normas de uso obligatorio de la cofia?', 'cuales son las normas de uso obligatorio de la cofia', 'El **uso de la cofia es obligatorio** y debe colocarse antes de entrar al vestier, asegurando que **cubra totalmente el cabello y los oídos** [1-3]. Únicamente debe ponerse o retirarse en el **baño**, estando prohibido hacerlo en pasillos, lockers o cafetería [2, 4]. Es obligatorio retirarla al **trasladarse entre plantas o salir a la calle**, pero al terminar el turno debe mantenerse puesta hasta salir del vestier [2, 5-7].', 'general', 1, '2026-04-14 21:21:44', '2026-04-14 21:21:44', 'notebooklm', 0, '2026-04-14 21:21:44');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (120, '¿Cómo se clasifican las áreas de trabajo según contaminación?', 'como se clasifican las areas de trabajo segun contaminacion', 'Las áreas se clasifican según su nivel de contaminación en Negras (alto nivel, sin aire controlado), Grises (nivel medio como vestieres o embalaje) y Blancas [1]. En las áreas blancas no debe existir ninguna clase de contaminación y el aire controlado debe funcionar de manera permanente [1, 2]. Es obligatorio cumplir con los instructivos de ingreso publicados para evitar cualquier contaminación en los productos [3].', 'general', 1, '2026-04-14 21:23:33', '2026-04-14 21:23:33', 'notebooklm', 0, '2026-04-14 21:23:33');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (121, '¿Cuáles son las prohibiciones estéticas para hombres y mujeres?', 'cuales son las prohibiciones esteticas para hombres y mujeres', 'Para las mujeres está prohibido el uso de cualquier tipo de maquillaje [1, 2]. Los hombres tienen prohibido dejarse la barba, el bigote o las patillas si tienen contacto directo con el producto [1]. Además, es obligatorio para todo el personal mantener las uñas cortas y sin esmalte, así como no portar joyas, aretes, anillos o relojes [1, 3].', 'general', 1, '2026-04-14 21:25:08', '2026-04-14 21:25:08', 'notebooklm', 0, '2026-04-14 21:25:08');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (122, '¿Cómo es el protocolo de ingreso para áreas grises?', 'como es el protocolo de ingreso para areas grises', 'Para ingresar a áreas grises debes usar cofia y protección auditiva sin maquillaje [1]. Luego, guarda tu ropa de calle y joyas en el locker, dejando tus zapatos en una bolsa para ponerte la blusa blanca [1]. Finalmente, lava y desinfecta tus manos, colócate el uniforme, usa la cinta para retirar partículas y ponte guantes desinfectados [1].', 'general', 1, '2026-04-15 13:14:01', '2026-04-15 13:14:01', 'notebooklm', 0, '2026-04-15 13:14:01');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (123, '¿Cómo se clasifican las faltas en el régimen disciplinario?', 'como se clasifican las faltas en el regimen disciplinario', 'Las faltas en Plastitec se clasifican principalmente en **leves** y **graves**, dependiendo de la naturaleza de la infracción cometida [1, 2]. Las faltas leves incluyen retardos injustificados de hasta cinco minutos, mientras que las graves abarcan actos como el engaño a la empresa o el incumplimiento reiterado de normas de seguridad [1, 3, 4]. Además, la gravedad de una falta puede verse influenciada por la existencia de situaciones agravantes o atenuantes al momento de imponer una sanción disciplinaria [5, 6].', 'general', 1, '2026-04-15 13:16:32', '2026-04-15 13:16:32', 'notebooklm', 0, '2026-04-15 13:16:32');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (124, '¿Cómo corregir un error en una planilla de control?', 'como corregir un error en una planilla de control', 'Para corregir un error, debes anular el dato con una línea diagonal, marcarlo con un asterisco y escribir el dato correcto junto a otro asterisco [1]. Finaliza incluyendo tu firma registrada y código asignado en la misma cara del documento [1]. Si realizas más de una corrección, usa un consecutivo al lado del asterisco para diferenciarlas [2]. Recuerda que está prohibido usar cinta, cuchilla o papel adhesivo [1].', 'general', 1, '2026-04-15 13:21:09', '2026-04-15 13:21:09', 'notebooklm', 0, '2026-04-15 13:21:09');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (125, '¿Cómo se clasifican las áreas de la planta según su nivel de contaminación?', 'como se clasifican las areas de la planta segun su nivel de contaminacion', '{
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (126, 'Niveles de contaminacion con ejemplos', 'niveles de contaminacion con ejemplos', 'Plastitec clasifica sus áreas de trabajo en tres niveles: Negras (contaminación alta, como baños y cafetería), Grises (nivel medio, como vestieres y peletizado) y Blancas (sin contaminación, como ensamble de bolsas PVC), donde el aire controlado es obligatorio. [1, 2]', 'general', 1, '2026-04-15 14:52:52', '2026-04-15 14:52:52', 'notebooklm', 0, '2026-04-15 14:52:52');
INSERT INTO knowledge_base (id, question_original, question_normalized, answer, category, usage_count, last_used, created_at, source, knowledge_version, last_validated) VALUES (127, '¿Cuáles son los requisitos para el lavado de manos?', 'cuales son los requisitos para el lavado de manos', 'Debes humedecer y aplicar jabón antibacterial en manos y brazos hasta el codo [1]. Frota palmas, dorsos con dedos entrelazados y cada uña durante un mínimo de 30 segundos [1, 2]. Para finalizar, enjuaga con suficiente agua y seca manos y brazos totalmente con una toalla de papel desechable [2].', 'general', 1, '2026-04-15 14:55:20', '2026-04-15 14:55:20', 'notebooklm', 0, '2026-04-15 14:55:20');
